{
  "tool": "trigger-environment-build",
  "description": "Start one DRAFT environment build of this run's own environment (fresh git checkout + install script, snapshotted at the end). OK to call during environment setup to validate the config before proposing, or when the user asks to trigger a build. Each build boots a pod and runs the full install for up to a few hours, so do not trigger casually outside setup. By default every repo in the environment builds at its default branch; pass `refs` (per repoUrl) to build specific branches/tags/SHAs — every repoUrl must belong to this run's environment. Note: for db-managed environments, a build created from a non-default ref can be tested but cannot be promoted to active later — only builds from every repo's default branch are promotable, so omit `refs` if you want a promotable build. Pass `environmentJson` to build with a custom config instead of the environment's saved db-backed config. For a greenfield run with no linked environment, `environmentJson` is required and creates a personal transitional draft automatically. The config is recorded durably on the build and never changes active environment settings. `environmentJson` is not supported for repo-file managed environments (those whose config is read from a repository environment.json — see `environmentJsonPath` in environment-info) and is rejected for them; test repo-file environments by building off a branch instead — create a branch, edit its environment.json, and build that branch via `refs`. Draft builds never become the build new agents boot from and skip warm-pool seeding, so they are safe for experiments; they appear in list-environment-builds (source AGENT, trigger MANUAL) and their logs are fetchable with environment-build-logs. Returns the new buildId immediately; the build runs in the background. Limited to a few in-flight builds per environment.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "refs": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "repoUrl": {
              "type": "string",
              "minLength": 1,
              "description": "Repository URL matching one of environment-info's top-level `repos` (same strings as environment.repos)."
            },
            "ref": {
              "type": "string",
              "minLength": 1,
              "description": "Branch, tag, or commit SHA to build this repo at."
            }
          },
          "required": [
            "repoUrl",
            "ref"
          ],
          "additionalProperties": false
        },
        "description": "Per-repository ref overrides. Every repoUrl must belong to this run's environment; repos left out build at their default branch."
      },
      "environmentJson": {
        "type": "object",
        "properties": {
          "install": {
            "type": "string",
            "description": "Idempotent repository bootstrap command run from /workspace after checkout (and when refreshing dependencies). Must terminate; use for dependency install and source-derived generation, not long-running servers, migrations, or tests. Prefer one command per line rather than chaining with &&."
          },
          "start": {
            "type": "string",
            "description": "Command run on each container start after install. Use for per-boot service startup with a non-daemonizing process (for example a dev server that stays attached). Do not use for dependency install or one-time setup."
          },
          "snapshot": {
            "type": "string",
            "description": "Saved base-environment snapshot ID. One of build, image, or snapshot typically defines the environment base."
          }
        },
        "additionalProperties": false,
        "description": "environment.json object used instead of the environment's saved db-backed config for this draft build. Property schema is authoritative (install, start, and optional snapshot). The override replaces saved config wholesale for the build, so include snapshot when the build should start from a READY take-environment-snapshot base. Required when this run has no linked environment (creates a personal transitional draft). Recorded on the build only; does not change active environment settings. Not supported for repo-file managed environments (see environmentJsonPath in environment-info)—test those via branch refs instead."
      }
    },
    "additionalProperties": false,
    "description": "Trigger a draft build for this run's environment. If the current run has no environment returned from environment-info, environmentJson is required.",
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}

{
  "tool": "propose-environment-json",
  "description": "Propose `environmentJson` for the user to review and edit before saving. Call after setup and end-to-end validation are complete. Always pass buildId when an environment build completed successfully; omit it only when no successful build exists. This lets Portal Save reuse the source snapshot that build validated. Call again with all final values if the proposal or the selected build changes. This tool records a proposal only; it does not modify the VM or save the environment.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "environmentJson": {
        "type": "object",
        "properties": {
          "install": {
            "type": "string",
            "description": "Idempotent repository bootstrap command run from /workspace after checkout (and when refreshing dependencies). Must terminate; use for dependency install and source-derived generation, not long-running servers, migrations, or tests. Prefer one command per line rather than chaining with &&."
          },
          "start": {
            "type": "string",
            "description": "Command run on each container start after install. Use for per-boot service startup with a non-daemonizing process (for example a dev server that stays attached). Do not use for dependency install or one-time setup."
          }
        },
        "additionalProperties": false,
        "description": "environment.json object for the user to review and edit before saving. Property schema is authoritative (install and/or start only). When a draft build was tested, pass top-level buildId so Save can reuse that build's validated snapshot—do not put snapshot on this object."
      },
      "buildId": {
        "type": "string",
        "minLength": 1,
        "description": "The successful environment build produced for this run and environment. Always pass this when a successful build exists; omit it only when no environment build completed successfully. Portal Save will reuse the source snapshot that this build validated after revalidating the build server-side."
      }
    },
    "required": [
      "environmentJson"
    ],
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}

